sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
        // 1. Initialize out-of-the-box REST message outbound wrapper
        var sm = new sn_ws.RESTMessageV2('Open AI Integration', 'AI Input');

        // Enforce strict output layout. Force the engine to output exact structural JSON.
        var systemPrompt = "You are an industrial automation safety parser. Review the vault telemetry variables.Respond ONLY with a valid minified JSON object matching this structural schema exactly:{\"safety_level\":\"CRITICAL\"|\"WARNING\"|\"NORMAL\",\"root_cause\":\"string\",\"remediation\":\"string\",\"pump_override\":true|false}.Do not include conversational fillers, markdown wrappers, or backticks.";

        var userContent = current.description.toString();

        var jsonPayload = {
            "model": "gpt-4o-mini", // Lower latency, higher cost-efficiency for industrial automation
            "messages": [
                { "role": "system", "content": systemPrompt },
                { "role": "user", "content": userContent }
            ],
            "temperature": 0.0, // Locked out to ensure mathematical determinism of data outputs
            "response_format": { "type": "json_object" } // Enforce structured output rendering
        };

        sm.setRequestBody(JSON.stringify(jsonPayload));

        // 2. Execute connection and benchmark transaction performance latency
        var startTime = new Date().getTime();
        var response = sm.execute();
        var endTime = new Date().getTime();

        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();

        var analysis;
        var isAiEvaluationSuccessful = false;

        // 3. Process operational evaluation blocks
        if (httpStatus == 200 && responseBody) {
            current.execution_latency = endTime - startTime;
            current.ai_json_output = responseBody;

            var parsedJson = JSON.parse(responseBody);
            if (parsedJson && parsedJson.choices && parsedJson.choices[0]) {
                var aiText = parsedJson.choices[0].message.content.trim();

                // Clean edge leaks of structural markdown notations
                aiText = aiText.replace(/```json/g, "").replace(/```/g, "").trim();

                analysis = JSON.parse(aiText);
                isAiEvaluationSuccessful = true;
            }
        }

        // 4. ENTERPRISE FALLBACK SYSTEM: Execute deterministic check if OpenAI is unreachable
        if (!isAiEvaluationSuccessful) {
            gs.warn("AI Vault Processor Outage: OpenAI returned status code " + httpStatus + ". Engaging automated hardcoded fail-safe framework.");

            // Re-parse metrics out of standard description string generated by Ingest endpoint
            var descStr = current.description.toString();
            var isPumpBroken = descStr.indexOf("PUMP_STATE: FAILED") !== -1;
            var isWaterSpiking = descStr.indexOf("METRICS_BREACHED: [Water Level]") !== -1 || descStr.indexOf("[Water Level]") !== -1;

            analysis = {
                "safety_level": (isPumpBroken || isWaterSpiking) ? "CRITICAL" : "WARNING",
                "root_cause": "OpenAI Inaccessible. Automatic hardcoded threshold fallback rules determined critical asset exposure risk.",
                "remediation": "FAIL-SAFE ESCALATION: Dispatch closest service unit immediately to inspect vault infrastructure metrics manually.",
                "pump_override": isPumpBroken ? false : true
            };
        }

        // 5. Extract evaluations safely and assign fields to record targets
        var safetyLevel = analysis.safety_level || "WARNING";
        var rootCause = analysis.root_cause || "Unknown field data anomaly detected.";
        var remediation = analysis.remediation || "Tech team requested for site validation diagnostics.";
        var pumpOverride = (analysis.pump_override === true || analysis.pump_override === "true");

        current.analysis = "=== AI REAL-TIME ANALYSIS ENGINE ===\n" +
            "Safety Assessment: " + safetyLevel + "\n" +
            "Root Cause: " + rootCause + "\n" +
            "Recommended Mitigation: " + remediation + "\n" +
            "Automated Pump Override Status: " + (pumpOverride ? "ACTIVE (FORCED START)" : "INACTIVE/HARDWARE FAILURE");

        // 6. Automatically escalate priorities based on computed analysis values
        if (safetyLevel === "CRITICAL") {
            current.impact = 1;
            current.urgency = 1; // Evaluates out dynamically to Priority 1 Critical Escalation

            if (current.short_description.indexOf("[⚠️ AI EMERGENCY]") === -1) {
                current.short_description = "[⚠️ AI EMERGENCY] " + current.short_description;
            }
        } else if (safetyLevel === "WARNING") {
            current.urgency = 2; // Priority 2 Alert Trigger
        }

        // 7. Commit database transactions while avoiding recursive loops
        current.setWorkflow(false);
        current.update();

    } catch (ex) {
        gs.error("AI Vault Processor Global Exception Intercepted: " + ex.message);

        // Critical System Panic Mode: Force P1 tracking if entire script bombs out to ensure tech is sent
        current.impact = 1;
        current.urgency = 1;
        current.short_description = "[⚠️ CRITICAL SYSTEM PANIC] " + current.short_description;
        current.analysis = "CRITICAL FAILURE: Safety processor script crashed entirely. Panic protocol engaged. Tech dispatch forced.";
        current.setWorkflow(false);
        current.update();
    }
})(current, previous);
